const lessons=[{"sentences":[{"speaker":"A","text":"Good morning and welcome to the central cycle hire office.","position":1,"audioStartSeconds":0,"audioEndSeconds":4.025625},{"speaker":"B","text":"Good morning I would like to book some bicycles for my family this weekend.","position":2,"audioStartSeconds":4.225625,"audioEndSeconds":8.906916666666667},{"speaker":"A","text":"I can certainly help you with that because we have several models available.","position":3,"audioStartSeconds":9.106916666666667,"audioEndSeconds":13.502},{"speaker":"B","text":"We need four bikes for adults and one bike for a younger child.","position":4,"audioStartSeconds":13.702,"audioEndSeconds":18.084208333333333},{"speaker":"A","text":"That is fine and the daily rental cost is twenty five pounds per bicycle.","position":5,"audioStartSeconds":18.284208333333332,"audioEndSeconds":23.142458333333334},{"speaker":"B","text":"Do we need to pay any extra money as a security deposit when we collect them.","position":6,"audioStartSeconds":23.342458333333333,"audioEndSeconds":28.25225},{"speaker":"A","text":"Yes we require a fully refundable deposit of fifty pounds for each booking.","position":7,"audioStartSeconds":28.45225,"audioEndSeconds":33.503791666666665},{"speaker":"B","text":"Should we return the bicycles to this exact office or can we use another location.","position":8,"audioStartSeconds":33.70379166666667,"audioEndSeconds":38.922875},{"speaker":"A","text":"You can leave them at our north station if this is more convenient for you.","position":9,"audioStartSeconds":39.122875,"audioEndSeconds":43.504333333333335},{"speaker":"B","text":"That sounds much better because our hotel is located near that station.","position":10,"audioStartSeconds":43.70433333333333,"audioEndSeconds":48.549708333333335},{"speaker":"A","text":"Please remember that you must bring your driving licence for identification purposes.","position":11,"audioStartSeconds":48.74970833333333,"audioEndSeconds":54.096875},{"speaker":"B","text":"I will bring that document along with my credit card on Saturday morning.","position":12,"audioStartSeconds":54.296875,"audioEndSeconds":58.923125},{"speaker":"A","text":"If you need to change your reservation later please call us before Friday afternoon.","position":13,"audioStartSeconds":59.123125,"audioEndSeconds":64.1495},{"speaker":"B","text":"Thank you for your helpful assistance and clear information today.","position":14,"audioStartSeconds":64.3495,"audioEndSeconds":68.51025}],"questions":[{"prompt":"Number of adult bikes: ______","answer":"four","evidenceSentence":4,"evidence":"four bikes for adults","explanation":"Người mua nói rõ họ cần bốn chiếc xe đạp cho người lớn."},{"prompt":"Daily rental cost: ______ pounds","answer":"twenty five","evidenceSentence":5,"evidence":"twenty five pounds","explanation":"Nhân viên nêu rõ giá thuê hàng ngày là hai mươi lăm bảng cho mỗi chiếc xe đạp."},{"prompt":"Security deposit: ______ pounds","answer":"fifty","evidenceSentence":7,"evidence":"fifty pounds","explanation":"Khoản tiền đặt cọc hoàn lại là năm mươi bảng cho mỗi lượt đặt."},{"prompt":"Return location: ______ station","answer":"north","evidenceSentence":9,"evidence":"north station","explanation":"Người thuê có thể trả xe tại trạm phía bắc."},{"prompt":"Required identification document: ______ licence","answer":"driving","evidenceSentence":11,"evidence":"driving licence","explanation":"Nhân viên nhắc khách hàng mang theo bằng lái xe."},{"prompt":"Change deadline: ______ afternoon","answer":"Friday","evidenceSentence":13,"evidence":"Friday afternoon","explanation":"Khách hàng được yêu cầu gọi điện trước chiều thứ sáu nếu muốn thay đổi đặt chỗ."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
